@startuml

class Bus {
  + LineNumber : string
}

class Trajectory {
  + Destination : string
  + Status : string
}

class Line {
  + Category : string
}

class TownAuthority {
  + ApprovalStatus : string
}

class ApprovalProcedure {
  + ProcedureNumber : int
}

class MENSOUser {
  + HomeAddress : string
  + OfficeAddress : string
  + WorkingHours : string
}

class MENSOCard {
  + CardNumber : string
}

class Trip {
  + Date : date
  + Time : time
}

class Invoice {
  + Amount : double
  + Discount : double
}

class Customer {
  + Name : string
}

Bus "0..*" -- "0..*" Trajectory : assigned to
Line "1" -- "1..*" Trajectory : groups
Trajectory "0..*" -- "0..1" TownAuthority : approved by
Trajectory "0..*" -- "0..*" ApprovalProcedure : undergoes
MENSOUser "1" -- "1" MENSOCard : possesses
MENSOUser "1" -- "0..*" Invoice : receives
MENSOUser "1" -- "0..*" Trip : performs
MENSOCard "1" -- "0..*" Trip : used for
Line "1" -- "0..*" Trip : traveled on
Invoice "1" -- "0..*" Trip : records

@enduml

